/**
 * Parameter types for each tool, mapped by tool name
 */
export type ToolParams = {
  [ACCOUNT_CAPABILITIES]: AccountCapabilitiesParams;
  [ACCOUNT_LOGIN]: AccountLoginParams;
  [ACCOUNT_LOGOUT]: AccountLogoutParams;
  [ACCOUNT_ME]: AccountMeParams;
  [ACCOUNT_CHANGE_PASSWORD]: AccountChangePasswordParams;
  [ACCOUNT_REGISTER]: AccountRegisterParams;
  [ACCOUNT_ADMIN_LIST_ROLES]: AccountAdminListRolesParams;
  [ACCOUNT_ADMIN_CREATE_ROLE]: AccountAdminCreateRoleParams;
  [ACCOUNT_ADMIN_DELETE_ROLE]: AccountAdminDeleteRoleParams;
  [ACCOUNT_ADMIN_UPDATE_ROLE]: AccountAdminUpdateRoleParams;
  [ACCOUNT_ADMIN_LIST_USERS]: AccountAdminListUsersParams;
  [ACCOUNT_ADMIN_CREATE_USER]: AccountAdminCreateUserParams;
  [ACCOUNT_ADMIN_GET_USER]: AccountAdminGetUserParams;
  [ACCOUNT_ADMIN_DISABLE_USER]: AccountAdminDisableUserParams;
  [ACCOUNT_ADMIN_ENABLE_USER]: AccountAdminEnableUserParams;
  [ACCOUNT_ADMIN_SET_USER_PASSWORD]: AccountAdminSetUserPasswordParams;
  [ACCOUNT_ADMIN_REVOKE_ROLE]: AccountAdminRevokeRoleParams;
  [ACCOUNT_ADMIN_GRANT_ROLE]: AccountAdminGrantRoleParams;
  [GREETING_GREET]: GreetingGreetParams;
};

/**
 * Invokes a tool by name using the SDK. A tool whose bindingStatus is
 * unsupported_multipart uploads a file, which tool parameters cannot carry;
 * invokeTool throws for it without sending a request.
 *
 * @param sdk - The initialized SDK instance
 * @param toolName - The namespaced tool name (e.g., "auth.sendMagicLink")
 * @param params - The parameters for the tool
 * @returns The result of the tool invocation
 * @throws Error if the tool name is not recognized
 *
 * @example
 * ```typescript
 * const sdk = new FixtureUserRoutesApiSDK({ baseUrl: 'https://api.example.com' });
 * const result = await invokeTool(sdk, 'auth.sendMagicLink', { email: 'user@example.com' });
 * ```
 */
export async function invokeTool<T extends ToolName>(
  sdk: FixtureUserRoutesApiSDK,
  toolName: T,
  params: ToolParams[T]
): Promise<unknown> {
  switch (toolName) {
    case ACCOUNT_CAPABILITIES:
      return sdk.account.capabilities();
    case ACCOUNT_LOGIN:
      return sdk.account.login({ login: (params as AccountLoginParams).login, password: (params as AccountLoginParams).password, session: (params as AccountLoginParams).session });
    case ACCOUNT_LOGOUT:
      return sdk.account.logout();
    case ACCOUNT_ME:
      return sdk.account.me();
    case ACCOUNT_CHANGE_PASSWORD:
      return sdk.account.changePassword({ current: (params as AccountChangePasswordParams).current, password: (params as AccountChangePasswordParams).password });
    case ACCOUNT_REGISTER:
      return sdk.account.register({ login: (params as AccountRegisterParams).login, name: (params as AccountRegisterParams).name, password: (params as AccountRegisterParams).password, session: (params as AccountRegisterParams).session });
    case ACCOUNT_ADMIN_LIST_ROLES:
      return sdk.accountAdmin.listRoles();
    case ACCOUNT_ADMIN_CREATE_ROLE:
      return sdk.accountAdmin.createRole({ name: (params as AccountAdminCreateRoleParams).name, permissions: (params as AccountAdminCreateRoleParams).permissions });
    case ACCOUNT_ADMIN_DELETE_ROLE:
      return sdk.accountAdmin.deleteRole((params as AccountAdminDeleteRoleParams).id);
    case ACCOUNT_ADMIN_UPDATE_ROLE:
      return sdk.accountAdmin.updateRole((params as AccountAdminUpdateRoleParams).id, { name: (params as AccountAdminUpdateRoleParams).name, permissions: (params as AccountAdminUpdateRoleParams).permissions });
    case ACCOUNT_ADMIN_LIST_USERS:
      return sdk.accountAdmin.listUsers();
    case ACCOUNT_ADMIN_CREATE_USER:
      return sdk.accountAdmin.createUser({ login: (params as AccountAdminCreateUserParams).login, name: (params as AccountAdminCreateUserParams).name, password: (params as AccountAdminCreateUserParams).password });
    case ACCOUNT_ADMIN_GET_USER:
      return sdk.accountAdmin.getUser((params as AccountAdminGetUserParams).id);
    case ACCOUNT_ADMIN_DISABLE_USER:
      return sdk.accountAdmin.disableUser((params as AccountAdminDisableUserParams).id);
    case ACCOUNT_ADMIN_ENABLE_USER:
      return sdk.accountAdmin.enableUser((params as AccountAdminEnableUserParams).id);
    case ACCOUNT_ADMIN_SET_USER_PASSWORD:
      return sdk.accountAdmin.setUserPassword((params as AccountAdminSetUserPasswordParams).id, { password: (params as AccountAdminSetUserPasswordParams).password });
    case ACCOUNT_ADMIN_REVOKE_ROLE:
      return sdk.accountAdmin.revokeRole((params as AccountAdminRevokeRoleParams).id, (params as AccountAdminRevokeRoleParams).roleId);
    case ACCOUNT_ADMIN_GRANT_ROLE:
      return sdk.accountAdmin.grantRole((params as AccountAdminGrantRoleParams).id, (params as AccountAdminGrantRoleParams).roleId);
    case GREETING_GREET:
      return sdk.greeting.greet();
    default:
      throw new Error(`Unknown tool: ${toolName}`);
  }
}

/**
 * Gets the tool definition for a given tool name
 */
export function getToolDefinition(toolName: ToolName): ToolDefinition {
  return toolDefinitions[toolName];
}

/**
 * Gets all tools that require authentication
 */
export function getAuthRequiredTools(): ToolDefinition[] {
  return Object.values(toolDefinitions).filter(t => t.requiresAuth);
}

/**
 * Gets all tools that don't require authentication
 */
export function getPublicTools(): ToolDefinition[] {
  return Object.values(toolDefinitions).filter(t => !t.requiresAuth);
}

/**
 * Gets all tools for a specific namespace
 */
export function getToolsForNamespace(namespace: string): ToolDefinition[] {
  return Object.values(toolDefinitions).filter(t => t.namespace === namespace);
}

/**
 * Validates that params contain all required fields for a tool
 */
export function validateToolParams(toolName: ToolName, params: Record<string, unknown>): { valid: boolean; missing: string[] } {
  const tool = toolDefinitions[toolName];
  const required = tool.parameters.required || [];
  const missing = required.filter(field => !(field in params) || params[field] === undefined);
  return { valid: missing.length === 0, missing };
}
